-- challenge chal_quiz_aam_121 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aam_121', (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aam-1-2' AND is_deleted = false LIMIT 1), 'tool-design-quiz', 'Read the tool call: what the model saw and what it got back', 'Two pieces of evidence from the support agent: the incident''s call replayed against the fixed tool, and a validator that reports one problem per turn.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
