DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_121');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_121');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_121'), 'The fixed tool definition, as listed to the model:

{"name":"get_learner_enrollment","description":"Read the enrollment of the learner who opened the current ticket in one course (the learner comes from the ticket, never from you). Returns status, progress and purchase date, or found: false.","parameters":{"type":"object","properties":{"course_slug":{"type":"string","description":"Course slug as in the course URL, e.g. react-hooks. Not an email, not a title: call search_courses first if you only have the title.","maxLength":80,"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$"}},"required":["course_slug"],"additionalProperties":false}}

Replay of ticket #9034 with a scripted model:

turn 1  model -> get_learner_enrollment {"course_slug":"minh.tran@example.com"}
        tool  -> error invalid_arguments: "course_slug" does not match pattern ^[a-z0-9]+(-[a-z0-9]+)*$
        handler calls: 0
turn 2  model -> search_courses {"query":"React Hooks"}

Statement: "The handler never ran for the email, and the error the model received names the parameter and its expected format, which gives it what it needs to look up the slug instead of telling the learner he is not enrolled."', 'single_choice'::question_type, 'True. The validator rejected the call before the handler ran (handler calls: 0), so no API request was made with an email as a course id. The message names the parameter and the pattern, and the description already points to search_courses when only the title is known, so turn 2 is a recovery rather than a wrong answer. Compare the incident: the old handler turned the 404 into null, which the model could not tell apart from "no enrollment". The misconception this checks is that a better description alone is enough: the description makes a correct first call more likely, the schema and a precise error catch the calls that are still wrong.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_121') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
