-- challenge chal_coding_aam_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aam_122', (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aam-1-2' AND is_deleted = false LIMIT 1), 'tool-registry', 'Tool registry: refuse vague tools, list them for the model, validate every call', 'Every tool the CodeDev support agent may call goes through one registry. Incident: a tool named getEnrollment with the description "Gets enrollment." and an undocumented string parameter id made the model pass a learner''s email as the course id; the API''s 404 became null and the agent told a paying learner he was not enrolled. Write three functions over registry: Map<string, ToolSpec>. registerTool(registry, spec) returns every problem with the spec (empty = registered; a rejected spec is not added), in this order: (1) name not matching ^[a-z][a-z0-9]*(_[a-z0-9]+)*$ or longer than 64 characters: name must be snake_case, 1-64 characters (got "<name>"); otherwise a name already in the registry: name "<name>" is already registered. (2) description trimmed: missing or empty: description is required; under 20 characters: description is shorter than 20 characters; over 300: description is longer than 300 characters. (3) parameters.type not "object": parameters must have type "object". (4) for each property in the order of parameters.properties, in this order: description missing or blank: parameter "<p>" needs a description; type not string, integer, number or boolean: parameter "<p>" has unsupported type "<type>"; minimum > maximum (both given): parameter "<p>" has minimum greater than maximum; minLength > maxLength: parameter "<p>" has minLength greater than maxLength; a pattern that new RegExp throws on: parameter "<p>" has an invalid pattern. (5) each entry of parameters.required, in order, that is not an own key of properties: required "<p>" is not a declared parameter. listTools(registry) returns the registered tools in registration order as { name, description, parameters: { type: "object", properties, required, additionalProperties: false } } with trimmed descriptions; each property is { type, description (trimmed) } followed by only the keywords the spec gives, in the order enum, minimum, maximum, minLength, maxLength, pattern (the runner prints it with JSON.stringify, so key order matters). validateCall(registry, { name, args }) returns every violation (empty = may run): an unknown name gives only unknown tool "<name>"; args that are not a plain object (null, an array, a string, a number) give only arguments must be an object; otherwise, for each property in properties order: absent (not an own key of args) and required: missing required argument "<p>" (absent and optional: nothing); wrong type (integer: Number.isInteger; number: a finite number; null is a wrong type): "<p>" must be <type>, with no further checks for it; then a value not in enum (===): "<p>" must be one of <each value as JSON, joined by ", ">; numbers below minimum: "<p>" must be >= <minimum>, above maximum: "<p>" must be <= <maximum>; strings (length = .length) shorter than minLength: "<p>" must be at least <n> characters, longer than maxLength: "<p>" must be at most <n> characters, not matching new RegExp(pattern).test: "<p>" does not match pattern <pattern>. Then each own key of args, in key order, that is not an own key of properties: unexpected argument "<key>" (inherited names such as constructor, toString or __proto__ are not parameters). Input (stdin): { "tools": ToolSpec[], "calls": [{ "name", "args" }], "summary"?: true }. The runner prints one line per registration, the listing, and one line per call (with summary: counts and a checksum of the call lines). Do not change the types or the test runner.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_122');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_122'), 1, 'For one call, do you want to stop at the first problem or collect them all? And which problems make every other check meaningless, so that they must be the only message?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_122'), 2, 'Look at Object.hasOwn versus the in operator (an object from JSON.parse can have own keys named constructor or __proto__, and every object inherits toString), at Number.isInteger for integer, and at where registry.set happens: only after every check of a spec found nothing. For the listing, build each property object key by key in the stated order instead of copying the spec.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_122'), 3, 'A similar tool on different input: get_certificate with course_slug (string, maxLength 10, pattern ^[a-z0-9-]+$) and year (integer, minimum 2020, maximum 2030), required ["course_slug"]. The call { "year": 2019.5, "lang": "vi" } gives three violations: missing required argument "course_slug"; "year" must be integer; unexpected argument "lang". The call { "course_slug": "Advanced SQL Course", "year": 2031 } also gives three: "course_slug" must be at most 10 characters; "course_slug" does not match pattern ^[a-z0-9-]+$; "year" must be <= 2030. Registering get_certificate a second time gives name "get_certificate" is already registered, and the first one stays in the listing.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_122'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
