VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_122'), 'The incident: the vague getEnrollment is rejected and the email is caught on the fixed tool', '{"tools":[{"name":"getEnrollment","description":"Gets enrollment.","parameters":{"type":"object","properties":{"id":{"type":"string"}},"required":["id"]}},{"name":"search_courses","description":"Search the CodeDev catalog by words from a course title. Returns up to 5 courses with slug, title and level. Use it when the learner names a course but you do not know its slug.","parameters":{"type":"object","properties":{"query":{"type":"string","description":"Words from the course title, e.g. React Hooks","minLength":2,"maxLength":100},"level":{"type":"string","description":"Only courses of this level","enum":["beginner","intermediate","advanced","expert"]}},"required":["query"]}},{"name":"get_learner_enrollment","description":"Read the enrollment of the learner who opened the current ticket in one course (the learner comes from the ticket, never from you). Returns status, progress and purchase date, or found: false.","parameters":{"type":"object","properties":{"course_slug":{"type":"string","description":"Course slug as in the course URL, e.g. react-hooks for https://app.codedev.test/courses/react-hooks. Not an email, not a title: call search_courses first if you only have the title.","pattern":"^[a-z0-9]+(-[a-z0-9]+)*$","maxLength":80}},"required":["course_slug"]}}],"calls":[{"name":"get_learner_enrollment","args":{"course_slug":"minh.tran@example.com"}},{"name":"search_courses","args":{"query":"React Hooks"}},{"name":"get_learner_enrollment","args":{"course_slug":"react-hooks"}},{"name":"getEnrollment","args":{"id":"minh.tran@example.com"}}]}', '"register getEnrollment: rejected: name must be snake_case, 1-64 characters (got \"getEnrollment\"); description is shorter than 20 characters; parameter \"id\" needs a description\nregister search_courses: ok\nregister get_learner_enrollment: ok\n