       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_122'), 'Every violation of a call is listed: parameters in order, then unexpected arguments', '{"tools":[{"name":"list_submissions","description":"List the ticket learner''s submissions for one challenge, newest first, with status and score.","parameters":{"type":"object","properties":{"challenge_id":{"type":"string","description":"Challenge id such as chal_ts_042","pattern":"^chal_[a-z0-9_]+$"},"status":{"type":"string","description":"Only submissions with this status","enum":["accepted","rejected","pending"]},"limit":{"type":"integer","description":"How many submissions to return","minimum":1,"maximum":50},"include_code":{"type":"boolean","description":"Include the submitted code (large)"}},"required":["challenge_id"]}}],"calls":[{"name":"list_submissions","args":{"status":"passed","limit":500,"user_id":"u_2291","challenge_id":"chal_ts_042"}},{"name":"list_submissions","args":{"limit":2.5,"include_code":"yes"}},{"name":"list_submissions","args":{"challenge_id":"chal_ts_042","limit":10}},{"name":"list_submissions","args":{}},{"name":"list_submissions","args":{"challenge_id":"ts_042","status":"accepted","include_code":false}}]}', '"register list_submissions: ok\ntools: [{\"name\":\"list_submissions\",\"description\":\"List the ticket learner''s submissions for one challenge, newest first, with status and score.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"challenge_id\":{\"type\":\"string\",\"description\":\"Challenge id such as chal_ts_042\",\"pattern\":\"^chal_[a-z0-9_]+$\"},\"status\":{\"type\":\"string\",\"description\":\"Only submissions with this status\",\"enum\":[\"accepted\",\"rejected\",\"pending\"]},\"limit\":{\"type\":\"integer\",\"description\":\"How many submissions to return\",\"minimum\":1,\"maximum\":50},\"include_code\":{\"type\":\"boolean\",\"description\":\"Include the submitted code (large)\"}},\"required\":[\"challenge_id\"],\"additionalProperties\":false