       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_122'), 'Registration: bad names, duplicates, descriptions, ranges, patterns and required entries', '{"tools":[{"name":"issue_refund","description":"Refund one order of the ticket learner in full. Needs approval by a support agent before it runs.","parameters":{"type":"object","properties":{"order_id":{"type":"string","description":"Order id such as ord_88","pattern":"^ord_"},"reason":{"type":"string","description":"Why, in one sentence, for the audit log","minLength":10,"maxLength":200}},"required":["order_id","reason"]}},{"name":"issue_refund","description":"Refund an order. Duplicate definition from a second tool file.","parameters":{"type":"object","properties":{"order_id":{"type":"string","description":"Order id such as ord_88","pattern":"^ord_"},"reason":{"type":"string","description":"Why, in one sentence, for the audit log","minLength":10,"maxLength":200}},"required":["order_id","reason"]}},{"name":"get__orders","description":"Search the CodeDev catalog by words from a course title. Returns up to 5 courses with slug, title and level. Use it when the learner names a course but you do not know its slug.","parameters":{"type":"object","properties":{"query":{"type":"string","description":"Words from the course title, e.g. React Hooks","minLength":2,"maxLength":100},"level":{"type":"string","description":"Only courses of this level","enum":["beginner","intermediate","advanced","expert"]}},"required":["query"]}},{"name":"_private_search","description":"Search the CodeDev catalog by words from a course title. Returns up to 5 courses with slug, title and level. Use it when the learner names a course but you do not know its slug.","parameters":{"type":"object","properties":{"query":{"type":"string","description":"Words from the course title, e.g. React Hooks","minLength":2,"maxLength":100},"level":{"type":"string","description":"Only courses of this level","enum":["beginner","intermediate"