       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_122'), 'Numbers and strings at the limits: ranges, numeric enum, integer vs number, lengths, pattern', '{"tools":[{"name":"get_leaderboard","description":"Read one page of the public leaderboard for a period, optionally filtered by score or nickname.","parameters":{"type":"object","properties":{"page":{"type":"integer","description":"Page number, starting at 1","minimum":1,"maximum":100},"size":{"type":"integer","description":"Rows per page","enum":[10,25,50]},"min_score":{"type":"number","description":"Only rows with a normalized score at least this","minimum":0,"maximum":1},"period":{"type":"string","description":"Leaderboard period","enum":["week","month","all_time"]},"nickname":{"type":"string","description":"Public nickname, lowercase","minLength":3,"maxLength":12,"pattern":"^[a-z0-9_]+$"}},"required":["period"]}}],"calls":[{"name":"get_leaderboard","args":{"period":"week","page":0}},{"name":"get_leaderboard","args":{"period":"week","page":100,"size":50}},{"name":"get_leaderboard","args":{"period":"week","page":101,"size":20}},{"name":"get_leaderboard","args":{"period":"week","size":"25","page":1}},{"name":"get_leaderboard","args":{"period":"month","min_score":0.5}},{"name":"get_leaderboard","args":{"period":"month","min_score":1.5}},{"name":"get_leaderboard","args":{"period":"month","min_score":1}},{"name":"get_leaderboard","args":{"period":"month","min_score":-0.1,"page":-3}},{"name":"get_leaderboard","args":{"period":"all_time","nickname":"ab"}},{"name":"get_leaderboard","args":{"period":"all_time","nickname":"Minh Tran!"}},{"name":"get_leaderboard","args":{"period":"all_time","nickname":"a_very_long_nickname"}},{"name":"get_leaderboard","args":{"period":"all_time","nickname":""}},{"name":"get_leaderboard","args":{"period":"year"}},{"name":"get_leaderboard","args":{"period":"Week"}},{"name":"get_leaderboard","args":{"page":2}}]}', '"register get_leaderboard: ok\ntools: [{\"name\"