       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_122'), 'The listing keeps registration order, trims descriptions and keeps only the given keywords', '{"tools":[{"name":"get_course_outline","description":"   Read the modules and lessons of one course, in order, with their titles.\n","parameters":{"type":"object","properties":{"course_slug":{"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$","maxLength":80,"description":"  Course slug, e.g. react-hooks  ","type":"string"},"module":{"maximum":20,"type":"integer","minimum":1,"description":"Only this module number","minLength":2}},"required":["course_slug"]}},{"name":"list_my_tickets","description":"List the open support tickets assigned to the current support agent.","parameters":{"type":"object","properties":{},"required":[]}},{"name":"search_courses","description":"Search the CodeDev catalog by words from a course title. Returns up to 5 courses with slug, title and level. Use it when the learner names a course but you do not know its slug.","parameters":{"type":"object","properties":{"query":{"type":"string","description":"Words from the course title, e.g. React Hooks","minLength":2,"maxLength":100},"level":{"type":"string","description":"Only courses of this level","enum":["beginner","intermediate","advanced","expert"]}},"required":["query"]}}],"calls":[{"name":"list_my_tickets","args":{}},{"name":"list_my_tickets","args":{"status":"open"}},{"name":"get_course_outline","args":{"course_slug":"react-hooks","module":3}},{"name":"get_course_outline","args":{"course_slug":"react-hooks","module":21}},{"name":"search_courses","args":{"query":"R","level":"Expert"}}]}', '"register get_course_outline: ok\nregister list_my_tickets: ok\nregister search_courses: ok\ntools: [{\"name\":\"get_course_outline\",\"description\":\"Read the modules and lessons of one course, in order, with their titles.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"course_slug\":{\"type\":\"string\",\"description\":\"Course sl