INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_132'), 1, 'For each proposed call, which of four things happened: the tool does not exist, its arguments are invalid, it ran and threw, or it ran and returned? And whatever happened, what must the model find in the transcript before you ask it for the next turn?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_132'), 2, 'Look at the order of your appends: the assistant message with all calls of the turn comes first, then exactly one tool message per call, without break or continue in between. Put the try/catch around tool.run only (not around model.next), keep the id counter outside the loop over turns, and check thrown values with instanceof Error and typeof before JSON.stringify.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_132'), 3, 'A similar run on different input: the task "Where is my certificate?", tools get_certificate and list_courses, and a script of one turn with two calls (get_certificate { "course_slug": 7 } and send_email {}), then a final answer. The transcript is: the user task; one assistant message with call_1 get_certificate and call_2 send_email; a tool message for call_1 with error invalid_arguments and the validator''s message; a tool message for call_2 with error unknown_tool listing get_certificate, list_courses; then the assistant''s final answer. The stats show 2 model turns, 2 calls, 0 executed, 1 invalid, 1 unknown, 0 failed, and neither tool ran.');
