VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_132'), 'The incident: an orders API timeout is fed back and the model recovers', '{"task":"Ticket #9120 from u_4410: I was charged twice for React Hooks, please check.","tools":[{"name":"list_orders","parameters":{},"outcomes":[{"throw":"orders API timed out after 5000 ms"},{"ok":[{"id":"ord_88","status":"paid"},{"id":"ord_89","status":"authorization_pending"}]}]},{"name":"get_order","parameters":{"order_id":{"type":"string","required":true}},"outcomes":[{"ok":{"id":"ord_88","course":"react-hooks","amount":299000,"status":"paid","paidAt":"2026-10-20T09:14:00Z"}},{"ok":{"id":"ord_89","course":"react-hooks","amount":299000,"status":"authorization_pending","createdAt":"2026-10-20T09:14:41Z"}}]}],"script":[{"toolCall":{"name":"list_orders","args":{}}},{"toolCall":{"name":"list_orders","args":{}}},{"toolCalls":[{"name":"get_order","args":{"order_id":"ord_88"}},{"name":"get_order","args":{"order_id":"ord_89"}}]},{"final":"You were charged once. ord_89 is a pending card authorization that your bank releases within a few days."}]}', '"user: Ticket #9120 from u_4410: I was charged twice for React Hooks, please check.\nassistant: call_1 list_orders {}\ntool call_1 list_orders error tool_failed: orders API timed out after 5000 ms\nassistant: call_2 list_orders {}\ntool call_2 list_orders ok [{\"id\":\"ord_88\",\"status\":\"paid\"},{\"id\":\"ord_89\",\"status\":\"authorization_pending\"}]\nassistant: call_3 get_order {\"order_id\":\"ord_88\"} | call_4 get_order {\"order_id\":\"ord_89\"}\ntool call_3 get_order ok {\"id\":\"ord_88\",\"course\":\"react-hooks\",\"amount\":299000,\"status\":\"paid\",\"paidAt\":\"2026-10-20T09:14:00Z\"}\ntool call_4 get_order ok {\"id\":\"ord_89\",\"course\":\"react-hooks\",\"amount\":299000,\"status\":\"authorization_pending\",\"createdAt\":\"2026-10-20T09:14:41Z\"}\nassistant final: You were charged once. ord_89 is a pending card authorization that your bank releases within a few days.\nanswer: You were charged once. ord_89 is a pending card authorization that your bank releases within a few days.\nstats: turns 4, calls 4, executed 4, invalid 0, unknown 0, failed 1\nexecutions: list_orders 2, get_order 2"', 3, true, false, 1),
