WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_221'), 'A tool in the first version of the codedev-content MCP server:

{
  "name": "get_progress",
  "description": "Progress of a learner in a course",
  "inputSchema": {
    "type": "object",
    "properties": {
      "userId":   { "type": "string", "pattern": "^u_[0-9]+$" },
      "courseId": { "type": "string" }
    },
