const MAX_LIMIT = 20;
function searchLessons(user: AuthedUser, args: { query: string; limit?: number; cursor?: string }) {
  const limit = Math.min(Math.max(args.limit ?? 10, 1), MAX_LIMIT);
  const after = args.cursor ? decodeCursor(args.cursor) : null;  // { rank, lessonId } of the last item sent
  const rows = db.lessons.search(args.query, { visibleTo: user.id, after, take: limit + 1 });
  const page = rows.slice(0, limit).map((r) => ({ lessonId: r.id, title: r.title, snippet: r.body.slice(0, 200) }));
  return { items: page, nextCursor: rows.length > limit ? encodeCursor(rows[limit - 1]) : null };
}

