-- module 3: Limits
UPDATE course.module SET title = 'Limits', updated_at = now() WHERE id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 3 AND is_deleted = false LIMIT 1);
INSERT INTO course.module (course_id, title, order_index)
SELECT (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp'), 'Limits', 3
WHERE NOT EXISTS (SELECT 1 FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 3 AND is_deleted = false);

-- lesson 3.1: Step limits & stop conditions (Sanity lesson-aam-3-1)
UPDATE course.lesson SET title = 'Step limits & stop conditions', order_index = 1, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 3 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-aam-3-1' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
