    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_311'), 'The repeated-call check in a pull request:

const key = call.name + " " + JSON.stringify(call.args);
sameInARow = key === lastKey ? sameInARow + 1 : 1;
lastKey = key;
if (sameInARow >= limits.maxSameCall) return stop("repeated_call");   // maxSameCall = 3

The model''s proposals in one run:
step 1  get_enrollment {"userId":"u-42","courseId":"sql-basics"}
step 2  get_enrollment {"courseId":"sql-basics","userId":"u-42"}
step 3  get_enrollment {"courseId":"sql-basics","userId":"u-42"}
step 4  get_enrollment {"userId":"u-42","courseId":"sql-basics"}

Statement: "This check stops the run at step 3, because steps 1 to 3 propose the same call."', 'single_choice'::question_type, 'False. The three calls ask the same question, but JSON.stringify keeps the key order the model wrote, so step 1''s key (userId first) differs from steps 2 and 3 (courseId first). The count is 1 at step 1, 1 at step 2 (new key), 2 at step 3 and back to 1 at step 4: the check does not fire at step 3. Models do not promise a stable key order, so the comparison needs a canonical form, for example keys sorted at every level before stringifying. The misconception is that JSON.stringify gives one string per value; it gives one string per object as written.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_311') AND order_index = 2)
    RETURNING id
)
