    ) AS o(option_text, is_correct);

-- challenge chal_coding_aam_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aam_312', (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aam-3-1' AND is_deleted = false LIMIT 1), 'agent-stop-conditions', 'Stop conditions for the support agent loop', 'The CodeDev support agent answers questions about orders, enrollments and lessons with three read-only tools. Its loop, runAgent(question, model, limits), only ends when the model gives a final answer, so a model that keeps calling tools keeps it running. Add stop conditions. A step is one call to model.next().

1. max_steps: before each model call, if steps already equals limits.maxSteps, stop.
2. final: a turn { "final": text } whose text is non-empty after trim stops the run with that answer.
3. no_final_answer: any other turn that is not a valid tool call stops the run: an empty or blank final, a missing or non-string final, a tool call without a non-empty string name. Model output is parsed JSON, so check its shape.
4. repeated_call: when the same tool call (same name and same canonical args: object keys sorted at every level) is proposed limits.maxSameCall times in a row, stop when that proposal arrives, without running the tool.
5. no_progress: progress means a tool result text not seen before in this run. After running a tool, if the last limits.maxNoProgress results in a row were all already seen, stop.

Tools never throw: problems come back as results starting with "error:" and count like any other result. runAgent returns { reason, steps, answer, partial }: answer is null unless the reason is "final"; partial lists every distinct tool result of the run in the order they first appeared.

Input (stdin, JSON): { "limits": { "maxSteps", "maxSameCall", "maxNoProgress" }, "runs": [ { "name", "question", "script": [turns] } ] }. The fake model returns one scripted turn per call and repeats its last turn when the script runs out. Output: a JSON array, one object per run: { "run", "reason", "steps", "answer", "partial" }.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
