INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_312'), 1, 'For each step, what has to be checked before the model is called, what right after its turn arrives, and what after the tool has run? Write the five conditions in that order before you write any code.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_312'), 2, 'Look at three places in runAgent: the top of the loop (the step budget), the moment the turn arrives (is it a usable final or a usable tool call, and is it the same call as the previous step?) and the line after callTool (was this result new?). Two counters that reset - one for identical calls in a row, one for results without anything new - and a Set of results seen so far are all the state you need.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_312'), 3, 'A similar check on other data: deciding whether two API requests are duplicates. { "q": "joins", "page": 2 } and { "page": 2, "q": "joins" } are the same request, so compare them after sorting the keys - also inside nested objects - and stringifying; arrays keep their order. For progress, a crawler that has fetched pages A, B, A, B, A has seen nothing new for 3 fetches in a row after the second B.');
