       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_312'), 'A model that looks up a new order every turn stops at max steps', '{"limits":{"maxSteps":6,"maxSameCall":3,"maxNoProgress":3},"runs":[{"name":"endless lookups","question":"Find all my orders.","script":[{"toolCall":{"name":"get_order","args":{"orderId":"o-2000"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2001"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2002"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2003"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2004"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2005"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2006"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2007"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2008"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2009"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2010"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2011"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2012"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2013"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2014"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2015"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2016"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2017"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2018"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-2019"}}}]}]}', '[{"run":"endless lookups","reason":"max_steps","steps":6,"answer":null,"partial":["order o-2000: ts-foundations, refunded","order o-2001: python-data, paid","order o-2002: sql-basics, paid","order o-2003: react-hooks, paid","order o-2004: node-streams, refunded","order o-2005: ts-foundations, paid"]}]', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_312'), 'The same call three times in a row stops, also with args in another key order', '{"limits":{"maxSteps":10,"maxSameCall":3,"maxNoProgress":5},"runs":[{"name":"same order again","question":"Is o-1003 paid?","script":[{"toolCall":{"name":"get_order","args":{"orderId":"o-1003"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-1003"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-1003"}}},{"final":"never reached"}]},{"name":"same enrollment, keys reordered","question":"How far am I in sql-basics?","script":[{"toolCall":{"name":"get_enrollment","args":{"userId":"u-42","courseId":"sql-basics"}}},{"toolCall":{"name":"get_enrollment","args":{"courseId":"sql-basics","userId":"u-42"}}},{"toolCall":{"name":"get_enrollment","args":{"courseId":"sql-basics","userId":"u-42"}}},{"final":"never reached"}]},{"name":"nested args reordered","question":"Find lessons on joins","script":[{"toolCall":{"name":"search_lessons","args":{"courseId":"sql-basics","query":"joins","filter":{"level":2,"tags":["sql","join"]}}}},{"toolCall":{"name":"search_lessons","args":{"filter":{"tags":["sql","join"],"level":2},"query":"joins","courseId":"sql-basics"}}},{"toolCall":{"name":"search_lessons","args":{"query":"joins","courseId":"sql-basics","filter":{"level":2,"tags":["sql","join"]}}}},{"final":"never reached"}]}]}', '[{"run":"same order again","reason":"repeated_call","steps":3,"answer":null,"partial":["order o-1003: react-hooks, paid"]},{"run":"same enrollment, keys reordered","reason":"repeated_call","steps":3,"answer":null,"partial":["enrollment u-42/sql-basics: 12/12 lessons done"]},{"run":"nested args reordered","reason":"repeated_call","steps":3,"answer":null,"partial":["search sql-basics \"joins\": 0 lessons"]}]', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_312'), 'Calls that alternate but bring nothing new stop as no progress', '{"limits":{"maxSteps":20,"maxSameCall":3,"maxNoProgress":3},"runs":[{"name":"ping-pong","question":"Compare o-11 and o-12","script":[{"toolCall":{"name":"get_order","args":{"orderId":"o-11"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-12"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-11"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-12"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-11"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-12"}}},{"final":"never reached"}]},{"name":"repeats not in a row, then an answer","question":"Check o-8 and o-9","script":[{"toolCall":{"name":"get_order","args":{"orderId":"o-8"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-8"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-9"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-8"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-8"}}},{"final":"o-8 was refunded, o-9 is paid."}]},{"name":"a new result resets the count","question":"Check my orders","script":[{"toolCall":{"name":"get_order","args":{"orderId":"o-5"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-6"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-5"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-6"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-7"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-5"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-6"}}},{"final":"Three orders found."}]}]}', '[{"run":"ping-pong","reason":"no_progress","steps":5,"answer":null,"partial":["order o-11: python-data, paid","order o-12: sql-basics, refunded"]},{"run":"repeats not in a row, then an answer","reason":"final","steps":6,"answer":"o-8 was refunded, o-9 is paid.","partial":["order o-8: react-hooks, refunded","order o-9: node-streams, paid"]},{"run":"a new result res