-- challenge chal_quiz_aam_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aam_321', (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aam-3-2' AND is_deleted = false LIMIT 1), 'agent-budget-quiz', 'Before or after the call?', 'Two budget checks from the CodeDev tutor agent: one that adds up usage after each call, and one that estimates the next call before it runs.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_321');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_321');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_321'), 'The budget check in the tutor agent loop (session budget: 50,000 tokens):

for (;;) {
  const res = await model.call({ messages: transcript, maxOutputTokens: 1000 });
  used += res.usage.inputTokens + res.usage.outputTokens;
  if (used > budget.maxTokens) return stop("max_tokens");
  // ...run the tool, append the result...
}

Usage log of session tutor-5521 (the learner pasted a long build log at step 4):
step 3  input 14,100  output 600   used 41,800
step 4  input 21,900  output 700   used 64,400  -> stop("max_tokens")

Statement: "This loop never spends more than the 50,000-token session budget, because it checks the total after every call."', 'single_choice'::question_type, 'False. The check runs after the call, so it can only notice that the budget was exceeded once the tokens are already spent: step 4 took the session from 41,800 to 64,400, 14,400 tokens over the limit. How far it overshoots depends on the size of the last call, and in an agent the input grows every step because the whole transcript is sent again, so the overshoot grows too. To stay within a budget, check before the call with an upper-bound estimate: the input tokens are known before sending (count them), and the output can be bounded by the maxOutputTokens cap. The misconception is that checking often is the same as checking first.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_321'), 'Price table (example numbers, USD per million tokens = micro-USD per token): large input 3, output 15. Every call is sent with maxOutputTokens = 1000.
Session cost budget: 60,000 micro-USD; spent so far: 50,000.

The tracker checks before the next call:
estimated cost = 2,000 input tokens * 3 + 1,000 * 15 = 21,000
50,000 + 21,000 = 71,000 > 60,000  -> stop("max_cost")

The team replays the same request without the check: the model writes 200 output tokens, so the call costs 2,000 * 3 + 200 * 15 = 9,000 micro-USD (59,000 in total).

Statement: "The check refused a call that would have fit in the budget, and that is the expected cost of an estimate that guarantees the budget is never exceeded."', 'single_choice'::question_type, 'True. The output length is unknown before the call, so a check that must never overshoot has to assume the worst case the API allows: the maxOutputTokens cap. That estimate is an upper bound, so it sometimes refuses calls that would have fit, like this one. You can reduce those refusals by lowering maxOutputTokens for steps that only need short answers, or by switching to a cheaper model near the end of a budget, but not by estimating the output from an average: an average is exceeded about half the time. The misconception is that a refused call that would have fit means the check is wrong; it means the check is conservative, which is the property you asked for.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_aam_322 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aam_322', (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aam-3-2' AND is_deleted = false LIMIT 1), 'agent-budget-tracker', 'Budget tracker: tokens, cost, time and tool calls', 'One BudgetTracker serves the CodeDev support agent across many sessions. The agent loop (in the test runner) asks it before every model call and every tool call and tells it what each call used. Write the tracker.

- startSession(userId, day): a session starts at clock.now(); per-session usage starts at 0; the user''s spend on that UTC day ("YYYY-MM-DD") carries over from earlier sessions.
- beforeModelCall(model, inputTokens): decide before the call, from an estimate. The output is estimated as config.maxOutputTokens (the cap: real output never exceeds it). Estimated tokens = inputTokens + maxOutputTokens; estimated cost = inputTokens * inputPerMTok + maxOutputTokens * outputPerMTok (prices are USD per million tokens = micro-USD per token, so all costs are integers). Return the first limit the call could exceed, in this order, or null: "unknown_model" (no price: fail closed), "max_tokens" (session tokens + estimate > session.maxTokens), "max_cost" (session cost + estimate > session.maxCostMicros), "daily_cost" (user''s spend that day + estimate > dailyCostMicrosPerUser), "max_wall_ms" (elapsed session time + modelCallMsEstimate > session.maxWallMs). Reaching a limit exactly is allowed.
- recordModelCall(model, usage): add the actual input/output tokens and their cost to the session and to the user''s daily spend.
- beforeToolCall(tool): "tool_calls:<tool>" if this call would exceed session.maxToolCalls[tool]; unlisted tools are unlimited. recordToolCall(tool) counts it.
- report(): { modelCalls, inputTokens, outputTokens, costMicros, wallMs, toolCalls (only tools called), remaining: { tokens, costMicros, wallMs, dailyCostMicros, toolCalls (every tool in maxToolCalls) } }. A remaining value never goes below 0.

Input (stdin, JSON): { "config", "sessions": [ { "id", "user", "start" (ISO, UTC), "turns": [ { "model", "input", "output", "ms", "tool"?, "toolMs"?, "final"? } ] } ] }. The fake model stops writing at maxOutputTokens; all times are on a fake clock. Output: a JSON array, one object per session: { "session", "user", "answered", "stoppedBy", ...report() }.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
