INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_322'), 1, 'Which of these numbers can you know before a model call, and which only after it? The tracker has to decide with the first kind and record the second kind - and some of what it records must survive startSession while the rest must not.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_322'), 2, 'Look at the two kinds of state: per-session counters (reset in startSession) and the daily spend, which belongs to the pair (user, day) and must outlive sessions - a Map keyed by both works. In beforeModelCall, compute the token and cost estimate once, then test the limits in the order the description lists, each as used + estimate > limit.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_322'), 3, 'A similar check on other numbers: a 10 MB upload quota with 9.2 MB used and a file whose size is only known as "at most 1 MB". 9.2 + 1 = 10.2 > 10, so refuse before uploading, even if the file turns out to be 0.5 MB. After an accepted upload, add the real size; the remaining quota shown to the user is max(0, 10 - used).');
