-- challenge chal_quiz_aam_331 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aam_331', (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aam-3-3' AND is_deleted = false LIMIT 1), 'retry-loop-quiz', 'Retry the tool, or tell the model?', 'Evidence from the support agent that ran for 40 minutes: its model-call trace, and a retry rule proposed in review.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_331');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_331');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_331'), 'Model-call trace of conversation support-9230 during the payments outage (model temperature 0):

14:12:03.120  model.next  transcript_len=3  -> get_refund_status {"orderId":"o-1003"}
14:12:04.410  tool get_refund_status  -> UNAVAILABLE payments-api returned 503
14:12:06.415  model.next  transcript_len=3  -> get_refund_status {"orderId":"o-1003"}
14:12:07.690  tool get_refund_status  -> UNAVAILABLE payments-api returned 503
14:12:09.700  model.next  transcript_len=3  -> get_refund_status {"orderId":"o-1003"}
... (730 model calls until 14:52:10, transcript_len=3 on every one)

Statement: "Every model call after the first one paid for input the model had already seen and gave it nothing new to decide on, because the failed tool call never reached the transcript."', 'single_choice'::question_type, 'True. transcript_len stays at 3 on every call: the loop catches the tool error, sleeps and asks the model again without appending anything. A model called with the same transcript at temperature 0 proposes the same call, so 729 of the 730 model calls bought the same decision again, and each one was billed for the full input. Asking the model again only makes sense after something changed: the error added as a tool result (so it can choose another tool, ask the learner, or answer), or a retry handled inside the tool layer, which does not need the model at all. The misconception is that re-asking the model is a retry; with the same input it is the same question.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_331') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_331'), 'A reviewer suggests this rule for the support agent''s tool calls:

const shouldRetry = (err: ToolError, attempt: number) => attempt < 3;   // any error, 3 retries
const delayMs = (attempt: number) => 500 * 2 ** attempt;           // 500, 1000, 2000 ms

Tool result log for one conversation:
get_order {"orderId":"o-9999"}  -> NOT_FOUND order o-9999 not found   (attempt 1)

Statement: "Retrying this NOT_FOUND three times with backoff is a safe default: it only costs a few seconds and the order may appear on a later attempt."', 'single_choice'::question_type, 'False. NOT_FOUND is a permanent error for this request: the order id is wrong, and asking again with the same id gets the same answer, so the three retries add 3.5 seconds of waiting and three useless calls to the orders API. Permanent errors (not found, invalid arguments, forbidden, unknown tool) should go straight back to the model as the tool result, so it can change course: ask the learner for the right number, or look the orders up by email. Retries with backoff and a maximum are for temporary errors - timeouts, 503, rate limits - that can clear up on their own. The misconception is that a retry is free insurance; for an error that cannot change, it is only delay and load, and during an outage it multiplies.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_331') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_aam_332 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aam_332', (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aam-3-3' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-agent-loop-never-stops', 'Spot the AI Mistake: an agent loop that never stops', 'The request sent to an AI coding assistant was: "Make the support agent retry tools until it gets an answer." Its version of runSupportAgent passed the tests (every tool answered) and was merged. During a payments API outage, one refund conversation ran for 40 minutes: the agent called get_refund_status, slept, asked the model again with the same transcript, got the same call back and did it again, more than 700 times. Fix runSupportAgent so that it follows the team''s agent policy (passed in as policy):

- Tool errors have a code. TIMEOUT, UNAVAILABLE and RATE_LIMITED are temporary: retry the same call, sleeping policy.baseBackoffMs * 2^(retry - 1) ms before retry 1, 2, 3... (clock.sleep), at most policy.maxRetries retries. NOT_FOUND, INVALID_ARGS, FORBIDDEN and UNKNOWN_TOOL are permanent: no retry.
- When a call fails for good (a permanent error, or a temporary one after the last retry), append the error to the transcript as the tool result "error <CODE>: <message>" so the model can change course.
- At most policy.maxSteps model calls; when the model proposes the same call (same name and args, object keys in any order) policy.maxSameCall times in a row, stop without running it again.
- When a limit stops the loop, escalate to a human: return { status: "escalated", reason: "max_steps" | "repeated_call", summary } with summary "<reason> after <steps> steps; last error: <CODE>: <message>" (the run''s last tool error, or "none").

Input (stdin, JSON): { "policy", "runs": [ { "name", "question", "faults"?, "script" } ] }. The fake model is deterministic: asked again with an unchanged transcript it returns the same turn; it moves on only when the transcript changed. Model calls take 1000 ms and tool attempts 200 ms on a fake clock. Output: a JSON array, one object per run, with the outcome, modelCalls, toolAttempts, elapsedMs and the tool results the model saw. The public tests (every tool answers) pass on the AI''s code; the hidden tests have a tool that always fails, one that fails every other attempt and a model that keeps proposing the same call.', 'open', 'hard'::difficulty_question, 'fix_bug', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_332');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_332'), 1, 'After a tool call fails, what is different the next time the loop calls model.next(transcript)? If nothing is, what will a deterministic model answer - and what in the loop could ever make it stop?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_332'), 2, 'Look at the catch block and at what the loop does after it. Three decisions belong there: is this error worth retrying at all (its code), how many retries have already happened for this call (and how long to sleep before the next), and what the model gets to read when the call fails for good. Then look at the top of the loop: nothing counts steps or compares the new call with the previous one.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_332'), 3, 'A similar case outside agents: a mail job sends a password-reset email. SMTP answers 421 (try again later): wait 1 s, 2 s, 4 s, then give up and record the failure. It answers 550 (no such mailbox): never retry; mark the address invalid so the next step can ask the user for a new one. And a supervisor that restarts the job when it fails gives up after N restarts in a row and pages a person with the last error.');
