INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_332'), 'Every tool answers: order lookup, then the answer', '{"policy":{"maxSteps":8,"maxSameCall":3,"maxRetries":3,"baseBackoffMs":500},"runs":[{"name":"refund status","question":"Was order o-1002 refunded?","script":[{"toolCall":{"name":"get_order","args":{"orderId":"o-1002"}}},{"toolCall":{"name":"get_refund_status","args":{"orderId":"o-1002"}}},{"final":"Yes: the refund for o-1002 was completed on 12 October."}]}]}', '[{"run":"refund status","status":"answered","answer":"Yes: the refund for o-1002 was completed on 12 October.","modelCalls":3,"toolAttempts":2,"elapsedMs":3400,"toolResults":["order o-1002: ts-foundations, refunded","refund o-1002: refund completed on 2026-10-12"]}]', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_332'), 'Every tool answers: find orders by email, then two lookups', '{"policy":{"maxSteps":8,"maxSameCall":3,"maxRetries":3,"baseBackoffMs":500},"runs":[{"name":"orders by email","question":"I paid twice, my email is lan@example.com","script":[{"toolCall":{"name":"find_orders","args":{"email":"lan@example.com"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-1001"}}},{"toolCall":{"name":"get_order","args":{"orderId":"o-1003"}}},{"final":"You have two orders for two different courses; neither is a duplicate."}]},{"name":"no tool needed","question":"Hi!","script":[{"final":"Hi! How can I help with your courses or orders?"}]}]}', '[{"run":"orders by email","status":"answered","answer":"You have two orders for two different courses; neither is a duplicate.","modelCalls":4,"toolAttempts":3,"elapsedMs":4600,"toolResults":["orders of lan@example.com: o-1001, o-1003","order o-1001: python-data, paid","order o-1003: sql-basics, paid"]},{"run":"no tool needed","status":"answered","answer":"Hi! How can I help with your courses or orders?","modelCalls":1,"toolAttempts":0,"elapsedMs":1000,"toolResults":[]}]', 3, true, false, 2),
