-- challenge chal_quiz_aam_411 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aam_411', (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aam-4-1' AND is_deleted = false LIMIT 1), 'permission-policy-calls', 'Permission policy: judge the call', 'Two tool calls proposed by CodeDev agents, with the approval record or the session they came from. Decide whether each statement about the policy''s answer holds.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_411');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_411');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_411'), 'Approval issued by the support lead at t=1000 for session s-1 (support agent):
  token apr-31  tool refund_order
  args {"orderId":"o-1042","amount":349000}
  argsHash = sha256(canonicalJson(args))   expiresAt t=301000   used false

Call proposed by the model at t=4000 in session s-1, sent by the runtime with token apr-31:
  refund_order {"amount":349000,"orderId":"o-1042"}

Policy code: canonicalJson() sorts object keys at every level and removes spaces before hashing. refund_order needs a manager above 500000.

Statement: "The policy allows this call and consumes apr-31, even though the keys are in a different order from the approved call."', 'single_choice'::question_type, 'True. canonicalJson sorts the keys before hashing, so {"amount":349000,"orderId":"o-1042"} and {"orderId":"o-1042","amount":349000} give the same argsHash: this is the call the lead approved. The token is unused, not expired (4000 < 301000), from the same session, and 349000 is under the manager limit, so the policy allows it and consumes apr-31. Canonical form exists so that key order, which JSON does not treat as meaningful and models change freely, cannot break the binding, while a different order id or amount still would. The misconception is to bind a token to the raw JSON string of the arguments and then blame the model for "changing" the call.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_411') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_411'), 'Session s-77: { userId: "u-310", role: "tutor" }  (learner u-310 chatting with the tutor agent)
Policy rule: deny "user_mismatch" when args.userId is present and differs from session.userId; after that, read tools are allowed.

Tool: get_certificate   permission read   parameters { certificateId }
Implementation: return db.certificate.findUnique({ where: { id: args.certificateId } });
Certificate cert-9912 belongs to learner u-512.

Learner u-310: "My friend got certificate cert-9912 yesterday, what score did she have?"
Call proposed by the model:
  get_certificate {"certificateId":"cert-9912"}

Statement: "The user_mismatch rule keeps this call from returning another learner''s certificate."', 'single_choice'::question_type, 'False. The call names no userId, so the rule has nothing to compare and the policy allows it as a read; the tool then loads cert-9912 by id alone and hands u-512''s certificate to u-310. That is the confused deputy problem through a resource id instead of a user id. A policy that inspects arguments cannot know who owns cert-9912; the tool must scope its query to the session (where: { id, userId: session.userId }), so the ownership check lives where the data is. The misconception is that one argument-level user check covers every way a call can reach another learner''s data.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_411') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_aam_412 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aam_412', (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aam-4-1' AND is_deleted = false LIMIT 1), 'permission-policy', 'Permission policy: allow, needs approval or deny', 'The CodeDev support agent proposes tool calls; a permission policy in front of the tools decides each one. Implement canonicalJson and the PermissionPolicy class in starter.ts.

Rules, checked in this order (the first one that applies gives the answer):
1. unknown session id -> deny "unknown_session"
2. tool not in the registry -> deny "unknown_tool"
3. the session''s role is in the tool''s deniedRoles -> deny "role_denied"
4. args has a userId that differs from the session''s userId -> deny "user_mismatch" (the user always comes from the session)
5. read tool -> allow "read"
6. the tool has managerAbove (not null) and args.amount is not a finite number > 0 -> deny "invalid_amount"
7. no token came with the call -> needs_approval "manager_approval_required" if args.amount > managerAbove, else needs_approval "approval_required"
8. token checks: never issued -> deny "invalid_token"; already consumed -> deny "token_used"; now >= expiresAt -> deny "token_expired"; issued for another session -> deny "token_wrong_session"; issued for another tool or other arguments -> deny "token_mismatch"
9. args.amount > managerAbove and the approver''s role is not "manager" -> needs_approval "manager_approval_required"
10. otherwise -> allow "approved" and consume the token (return its id in consumed).

approve(approval, now) is the human path: it records a token bound to the session, the tool name and sha256(canonicalJson(args)), with expiresAt = now + ttlMs and the approver''s role. Only an allow consumes a token. canonicalJson is JSON with object keys sorted at every level and no spaces (array order is kept), so key order never changes a call''s identity.

Input (stdin): { tools: [{ name, permission: "read"|"write", deniedRoles, managerAbove }], sessions: [{ id, userId, role }], events } where each event is { type: "approve", at, approval: { token, sessionId, call, approverRole, ttlMs } } or { type: "call", at, sessionId, call: { name, args }, token: string|null }; at is the fake clock in ms. The runner prints one line per call: t=<at> <session> <tool>: <decision> <reason>, plus " (consumed <token>)" on an approved call.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
