INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_412'), 1, 'For a write call that arrives with a token, which facts about the token must all be true before the call may run, and which of them change after it runs once?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_412'), 2, 'Look at what approve() stores: the token must remember the session, the tool, a hash of the canonical arguments, the approver''s role, its expiry and whether it was used. decide() then walks the numbered rules in order and returns at the first match.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_412'), 3, 'A similar case on other data: a coupon code bound to { cart: "c-9", total: 120 } that expires at t=5000. Redeeming it for cart c-9 with { total: 120 } at t=4000 succeeds once and marks it spent; the same code again says "spent"; at t=5000 it says "expired"; for cart c-8 it says "wrong cart" and stays unspent.');
