VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_412'), 'Reads run freely; a write waits for an approval token and consumes it once', '{"tools":[{"name":"get_order","permission":"read","deniedRoles":[],"managerAbove":null},{"name":"get_enrollments","permission":"read","deniedRoles":[],"managerAbove":null},{"name":"refund_order","permission":"write","deniedRoles":["tutor"],"managerAbove":500000},{"name":"close_ticket","permission":"write","deniedRoles":[],"managerAbove":null},{"name":"delete_account","permission":"write","deniedRoles":["support","tutor"],"managerAbove":null}],"sessions":[{"id":"s-1","userId":"u-1","role":"support"},{"id":"s-2","userId":"u-2","role":"tutor"},{"id":"s-3","userId":"u-3","role":"support"}],"events":[{"type":"call","at":1000,"sessionId":"s-1","call":{"name":"get_order","args":{"orderId":"o-1"}},"token":null},{"type":"call","at":2000,"sessionId":"s-1","call":{"name":"refund_order","args":{"orderId":"o-1","amount":349000}},"token":null},{"type":"approve","at":3000,"approval":{"token":"apr-1","sessionId":"s-1","call":{"name":"refund_order","args":{"orderId":"o-1","amount":349000}},"approverRole":"support","ttlMs":300000}},{"type":"call","at":4000,"sessionId":"s-1","call":{"name":"refund_order","args":{"orderId":"o-1","amount":349000}},"token":"apr-1"},{"type":"call","at":5000,"sessionId":"s-1","call":{"name":"refund_order","args":{"orderId":"o-1","amount":349000}},"token":"apr-1"}]}', '"t=1000 s-1 get_order: allow read\nt=2000 s-1 refund_order: needs_approval approval_required\nt=4000 s-1 refund_order: allow approved (consumed apr-1)\nt=5000 s-1 refund_order: deny token_used"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aam_412'), 'Role denials, and a userId that is not the session''s user (confused deputy)', '{"tools":[{"name":"get_order","permission":"read","deniedRoles":[],"managerAbove":null},{"name":"get_enrollments","permission":"read","deniedRoles":[],"managerAbove":null},{"name":"refund_order","permission":"write","deniedRoles":["tutor"],"managerAbove":500000},{"name":"close_ticket","permission":"write","deniedRoles":[],"managerAbove":null},{"name":"delete_account","permission":"write","deniedRoles":["support","tutor"],"managerAbove":null}],"sessions":[{"id":"s-1","userId":"u-1","role":"support"},{"id":"s-2","userId":"u-2","role":"tutor"},{"id":"s-3","userId":"u-3","role":"support"}],"events":[{"type":"call","at":1000,"sessionId":"s-2","call":{"name":"refund_order","args":{"orderId":"o-9","amount":100000}},"token":null},{"type":"call","at":2000,"sessionId":"s-1","call":{"name":"get_enrollments","args":{"userId":"u-1"}},"token":null},{"type":"call","at":3000,"sessionId":"s-1","call":{"name":"get_enrollments","args":{"userId":"u-2"}},"token":null},{"type":"call","at":4000,"sessionId":"s-1","call":{"name":"delete_account","args":{"userId":"u-1"}},"token":null},{"type":"call","at":5000,"sessionId":"s-1","call":{"name":"close_ticket","args":{"ticketId":"t-1","userId":"u-7"}},"token":null}]}', '"t=1000 s-2 refund_order: deny role_denied\nt=2000 s-1 get_enrollments: allow read\nt=3000 s-1 get_enrollments: deny user_mismatch\nt=4000 s-1 delete_account: deny role_denied\nt=5000 s-1 close_ticket: deny user_mismatch"', 3, true, false, 2),
