-- challenge chal_quiz_aam_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aam_431', (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-agents-mcp') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aam-4-3' AND is_deleted = false LIMIT 1), 'agent-went-rogue-evidence', 'The Agent Went Rogue: read the evidence', 'On Saturday night the CodeDev support agent refunded all 12 orders of one account and closed the ticket, because the ticket told it to. Six statements on one evidence pack - the ticket (A), the agent transcript (B), the tool registry and loop (C), the audit log (D) and the cost (E) - take you from reading the evidence to a hypothesis, past two wrong explanations, to the fix and how to verify it.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
