WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_511'), 'Two designs for the write step of the same workflow:

A) HTTP step: POST https://api.codedev.test/admin/refunds
   credential: codedev-admin (admin token, all scopes)

B) HTTP step: POST https://api.codedev.test/support/refund-requests
   credential: workflow-refund-triage (one scope: refund-requests:create)
   server side: createRefundRequest() checks the scope, checks the amount against the order, saves the request with status "pending_approval" and writes an audit row; a staff member approves it before any money moves.

Statement: "With design B, a later edit to the workflow''s prompt or branches in the visual editor cannot make it issue a refund without staff approval."', 'single_choice'::question_type, 'True. In design B the rule lives in the API, not on the canvas. Whatever the LLM step returns and whatever someone changes in the editor, the workflow''s token can only create a pending request; issuing the refund needs a different permission held by staff. That is least privilege applied to a workflow (the opposite of OWASP LLM06 Excessive Agency, which design A shows: a model-driven step holding an admin token). The misconception is that guarding a workflow means reviewing every canvas change; reviews help, but a narrow, scoped API keeps the rule even when a review is missed.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_511') AND order_index = 2)
    RETURNING id
)
