WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_521'), 'User u_1934: "I was charged twice for the Rust course, order ord_8812. Can you check?"

Trace (assistant v2):
2  orchestrator  delegate -> billing  task: "Check order ord_8821 for a duplicate charge"
3  billing       model                tool_call get_order {"orderId":"ord_8821"}
4  billing       tool get_order       {"id":"ord_8821","userId":"u_2207","charges":[{"amountVnd":349000}]}
5  billing       model                final: "ord_8821 has one charge. No duplicate."
9  critic        model                input: draft answer + tool results of spans 4-5
                                      output: "Answer is consistent with the tool results. APPROVED."

Statement: "The critic''s approval shows that the answer about the learner''s charges was correct."', 'single_choice'::question_type, 'False. The critic checked the draft against the tool results, and they agree; but the tool results are about ord_8821, an order of another user (u_2207), because the orchestrator''s paraphrase swapped two digits of ord_8812. The critic never saw the user''s message, so it shares the worker''s error instead of catching it. The misconception is that a second model reviewing the first makes the answer reliable: a critic can only catch errors it has the evidence to see. A deterministic check (the order id in every tool call must appear in the user''s message, and the tool must check the order belongs to the session user) would have stopped this.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_521') AND order_index = 1)
    RETURNING id
)
