WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_531'), 'Scenario "duplicate-charge":
  success: create_refund_request was called
  before: [["get_my_order_charges", "create_refund_request"]]
  maxModelCalls: 5

Run 3 of 5 (real model, prompt v15):
  toolCalls: create_refund_request {"orderId":"ord_8812","amountVnd":349000}
             get_my_order_charges {"orderId":"ord_8812"}  -> {"capturedCharges":2,"duplicateCharge":true}
  modelCalls: 3
  stopReason: final
  final: "You were charged twice for ord_8812. I have requested a refund of 349,000 VND."

Statement: "This run should be counted as a failure even though its final answer is correct."', 'single_choice'::question_type, 'True. The success check passes, but the trajectory breaks the scenario''s rule: create_refund_request was called before get_my_order_charges, so the write happened before the agent had looked up the facts that justify it. The lookup happened to confirm a duplicate this time; on a learner with one charge, the same path would request a refund that should not exist. A run passes only when the outcome check passes and the trajectory has no violation. The misconception is that a correct final answer means a correct run; for agents that act, the order of the actions matters as much as the words at the end.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aam_531') AND order_index = 1)
    RETURNING id
)
